ST.xhtml:
(* ================= AXIS402: CiA 402 drive model (subset) ================= *)
(* state: 1=SOD 2=RTSO 3=SO 4=OE 5=QSA 6=FaultReaction 7=FaultActive         *)
(* cw bits used: 0..3 command | 4 new setpoint | 7 fault reset | 8 halt      *)
(* sw bits used: 0 ready |1 switched on |2 op-enabled |3 fault |4 volt |5 qs *)
(*              inactive |6 SOD |10 target reached |12 setpoint acknowledge  *)

cmd := cw AND 16#000F;

(* ---- fault reset (cw bit7) ---- *)
IF state = 7 AND (cw AND 16#0080) <> 0 THEN
    state := 1;
    v := 0.0;
END_IF;

(* ---- drive state machine on cw low-nibble commands ---- *)
CASE state OF
    1:  IF cmd = 16#06 THEN state := 2; END_IF;
    2:  IF cmd = 16#07 THEN state := 3;
        ELSIF cmd = 16#0F THEN state := 4;
        ELSIF cmd = 16#00 THEN state := 1;
        END_IF;
    3:  IF cmd = 16#0F THEN state := 4;
        ELSIF cmd = 16#06 THEN state := 2;
        ELSIF cmd = 16#00 THEN state := 1;
        ELSIF cmd = 16#02 THEN state := 5;
        END_IF;
    4:  IF cmd = 16#07 THEN state := 3;
        ELSIF cmd = 16#06 THEN state := 2;
        ELSIF cmd = 16#00 THEN state := 1;
        ELSIF cmd = 16#02 THEN state := 5;
        END_IF;
    5:  IF v = 0.0 THEN
            IF cmd = 16#0F THEN state := 4;
            ELSIF cmd = 16#06 THEN state := 2;
            ELSIF cmd = 16#00 THEN state := 1;
            END_IF;
        END_IF;
    6:  IF v = 0.0 THEN state := 7; END_IF;
END_CASE;

(* ---- Profile Position: 电平锁存（OE 且 bit4=1 时，目标有变化或未被确认即锁存） ---- *)
IF state = 4 AND (cw AND 16#0010) <> 0 THEN
    IF target < 0 OR target > 100 THEN
        state := 6;                       (* target outside travel -> fault reaction *)
    ELSIF (INT_TO_REAL(target) <> tgt) OR NOT sp_ack THEN
        tgt := INT_TO_REAL(target);
        sp_ack := TRUE;
    END_IF;
END_IF;
IF sp_ack AND (cw AND 16#0010) = 0 THEN
    sp_ack := FALSE;                      (* acknowledge drops after master clears bit4 *)
END_IF;

(* ---- trapezoidal trajectory generator (runs in OE; halt on cw bit8) ---- *)
IF state = 4 THEN
    IF (cw AND 16#0100) <> 0 THEN
        IF v > 0.0 THEN v := MAX(0.0, v - ACCEL * SCAN_T);
        ELSIF v < 0.0 THEN v := MIN(0.0, v + ACCEL * SCAN_T);
        END_IF;
    ELSE
        dist := tgt - demand;
        stop_d := (v * v) / (2.0 * ACCEL);
        IF ABS(dist) <= stop_d THEN
            IF dist >= 0.0 THEN v := MAX(0.0, v - ACCEL * SCAN_T);
            ELSE v := MIN(0.0, v + ACCEL * SCAN_T);
            END_IF;
            IF v = 0.0 AND ABS(dist) <= POSWIN THEN demand := tgt; END_IF;
        ELSE
            IF dist > 0.0 THEN v := MIN(VMAX, v + ACCEL * SCAN_T);
            ELSE v := MAX(-VMAX, v - ACCEL * SCAN_T);
            END_IF;
        END_IF;
    END_IF;
    (* target-reached 由状态字 bit10 报告；ack 不在此清除 *)
ELSIF state = 5 OR state = 6 THEN
    IF v > 0.0 THEN v := MAX(0.0, v - QS_DECEL * SCAN_T);
    ELSIF v < 0.0 THEN v := MIN(0.0, v + QS_DECEL * SCAN_T);
    END_IF;
ELSE
    v := 0.0;                             (* not enabled: no motion *)
END_IF;

(* demand 随速度推进（OE 定位与 QSA/FRA 减速路径都随动，误差不累积） *)
IF state >= 4 AND state <= 6 THEN
    demand := demand + v * SCAN_T;
END_IF;

(* ---- position servo loop: demand vs encoder -> signed motor velocity cmd ---- *)
(* 仅 OE/QSA/FRA 输出（快停与故障反应按减速曲线走）；失能/故障锁定状态电机指令为零 *)
IF state >= 4 AND state <= 6 THEN
    err := demand - INT_TO_REAL(pos_fb);
    IF v = 0.0 AND ABS(err) <= 1.5 THEN
        v_out := 0.0;   (* 静止死区：消除编码器量化的保持抖动 *)
    ELSE
    v_out := v + KP * err;
    IF v_out > 120.0 THEN v_out := 120.0; END_IF;
    IF v_out < -120.0 THEN v_out := -120.0; END_IF;
    END_IF;
ELSE
    v_out := 0.0;
END_IF;
v_cmd := REAL_TO_INT(v_out);

(* ---- status word (subset encoding) ---- *)
sw := 0;
CASE state OF
    1: sw := 16#0040;
    2: sw := 16#0031;
    3: sw := 16#0033;
    4: sw := 16#0037;
    5: sw := 16#0014;
    7: sw := 16#0018;
END_CASE;
IF state = 4 THEN
    IF ABS(tgt - demand) <= POSWIN AND v = 0.0 AND (cw AND 16#0100) = 0 THEN
        sw := sw OR 16#0400;
    END_IF;
    IF sp_ack THEN
        sw := sw OR 16#1000;
    END_IF;
END_IF;

(* MC_Power (IEC 61131-4 subset): auto power-up sequence *)
(* SOD --0x06--> RTSO --0x07--> SO --0x0F--> OE ; Disable -> shutdown 0x06 *)
IF Enable AND pstep = 4 AND (sw AND 16#0004) = 0 AND (sw AND 16#0008) = 0 THEN
    pstep := 0;                             (* lost OE without fault -> restart sequence *)
END_IF;
IF Enable THEN
    CASE pstep OF
        0: cw := (cw AND 16#00F0) OR 16#0006;  pstep := 1;
        1: IF (sw AND 16#0001) <> 0 THEN cw := (cw AND 16#00F0) OR 16#0007; pstep := 2; END_IF;
        2: IF (sw AND 16#0002) <> 0 THEN cw := (cw AND 16#00F0) OR 16#000F; pstep := 3; END_IF;
        3: IF (sw AND 16#0004) <> 0 THEN pstep := 4; END_IF;
    END_CASE;
ELSE
    cw := (cw AND 16#00F0) OR 16#0006;       (* shutdown *)
    pstep := 0;
END_IF;
Status := (sw AND 16#0004) <> 0;           (* operation enabled *)
Error := (sw AND 16#0008) <> 0;

(* MC_Reset: CiA 402 fault reset (cw bit7 pulse) *)
IF Execute AND NOT exe_prev THEN
    busy := TRUE;
END_IF;
exe_prev := Execute;
IF busy THEN
    IF (sw AND 16#0008) <> 0 THEN
        cw := cw OR 16#0080;                 (* reset fault *)
    ELSE
        cw := cw AND 16#FF7F;                (* fault cleared -> drop bit7 *)
        busy := FALSE;
    END_IF;
END_IF;
Done := busy = FALSE AND (sw AND 16#0008) = 0 AND NOT Execute;

(* MC_MoveAbsolute: CiA 402 profile-position handshake *)
(* master: set new-setpoint(bit4) -> drive acknowledges(bit12) -> clear bit4  *)
(* Done on target-reached(bit10) *)
IF Execute AND NOT exe_prev THEN
    target := Position;                      (* 边沿扫描立即落目标并请求设定点 *)
    cw := (cw AND 16#FFEF) OR 16#0010;
    mov_busy := TRUE;
    ack_seen := FALSE;
END_IF;
exe_prev := Execute;

IF busy THEN
    IF (sw AND 16#0004) = 16#0000 OR (sw AND 16#0008) <> 0 THEN
        cw := cw AND 16#FFEF;                (* abort: leave no pending setpoint *)
        mov_busy := FALSE;                   (* not enabled / fault -> abort *)
    ELSIF NOT ack_seen THEN
        IF (cw AND 16#0010) = 0 THEN
            cw := cw OR 16#0010;             (* retry setpoint request *)
        END_IF;
        IF (sw AND 16#1000) <> 0 THEN
            cw := cw AND 16#FFEF;            (* acknowledge seen -> clear bit4 *)
            ack_seen := TRUE;
        END_IF;
    ELSIF (sw AND 16#0400) <> 0 THEN
        mov_busy := FALSE;                   (* target reached -> command complete *)
    END_IF;
END_IF;
Busy := mov_busy;
Done := ack_seen AND (sw AND 16#0400) <> 0 AND NOT busy;
Error := (sw AND 16#0008) <> 0;

(* MC_MoveJog: chase-target jog (target rides ahead of *)
(* feedback while a jog input is held; drive decelerates on release).       *)
IF (JogForward OR JogBackward) AND (sw AND 16#0004) <> 0 THEN
    IF JogForward AND pos_fb < 95 THEN
        target := pos_fb + 6;
    ELSIF JogBackward AND pos_fb > 5 THEN
        target := pos_fb - 6;
    END_IF;
    last_tgt := target;
    IF (cw AND 16#0010) = 0 THEN
        cw := cw OR 16#0010;
    END_IF;
    Busy := TRUE;
ELSE
    (* 所有权判定：仅当挂起的设定点是本块上次追赶值时才收尾，避免误杀其他块的新指令 *)
    IF (cw AND 16#0010) <> 0 AND target = last_tgt THEN
        target := pos_fb;                    (* release: hold where we are *)
        cw := cw AND 16#FFEF;                (* and drop new-setpoint bit *)
    END_IF;
    Busy := FALSE;
END_IF;

(* MC_Stop: CiA 402 quick stop (cw = 0x02), controlled *)
(* deceleration; axis re-enabled by MC_Power once Execute drops.            *)
IF Execute THEN
    cw := (cw AND 16#00F0) OR 16#0002;
    Busy := TRUE;
    Done := FALSE;
ELSIF Busy THEN
    Busy := FALSE;                           (* quick stop latched in drive until re-command *)
    Done := TRUE;
END_IF;

(* MC_Home (simplified): absolute move to machine zero 0. *)
mv(Execute := Execute, Position := 0, cw := cw, sw := sw, target := target);
Done := mv.Done AND NOT Execute;
exe_prev := Execute;

(* ---- program identity ---- *)
prog_id := 1;

(* ---- 扫描头：采样各驱动上一扫描的状态字到诊断字（MC 块与主站共用） ---- *)
x_sw := ax_x.sw;
y_sw := ax_y.sw;
z_sw := ax_z.sw;

(* ---- 应用层：使能 / 故障复位 / 快停（顺序即优先级：快停最后落笔，覆盖使能命令） ---- *)
pwr_x(Enable := run AND NOT quickstop, cw := x_cw, sw := x_sw);
pwr_y(Enable := run AND NOT quickstop, cw := y_cw, sw := y_sw);
pwr_z(Enable := run AND NOT quickstop, cw := z_cw, sw := z_sw);

rs_x(Execute := cmd_reset, cw := x_cw, sw := x_sw);

st_x(Execute := quickstop, cw := x_cw, sw := x_sw);
st_y(Execute := quickstop, cw := y_cw, sw := y_sw);
st_z(Execute := quickstop, cw := z_cw, sw := z_sw);

(* ---- 应用层：定位 / 回零 / 点动 / 故障注入 ---- *)
go_x(Execute := cmd_go, Position := x_sp, cw := x_cw, sw := x_sw, target := x_tgt);
go_y(Execute := cmd_go, Position := y_sp, cw := y_cw, sw := y_sw, target := y_tgt);
go_z(Execute := cmd_go, Position := z_sp, cw := z_cw, sw := z_sw, target := z_tgt);

hm_x(Execute := cmd_home, cw := x_cw, sw := x_sw, target := x_tgt);
hm_y(Execute := cmd_home, cw := y_cw, sw := y_sw, target := y_tgt);
hm_z(Execute := cmd_home, cw := z_cw, sw := z_sw, target := z_tgt);

jg_x(JogForward := jog_fwd, JogBackward := jog_rev,
     cw := x_cw, sw := x_sw, target := x_tgt, pos_fb := x_fb);

fx(Execute := inject_fault, Position := 150, cw := x_cw, sw := x_sw, target := x_tgt);

(* ---- 驱动器实例（读 cw/target/fb，写 sw/v_cmd） ---- *)
ax_x(cw := x_cw, target := x_tgt, pos_fb := x_fb);
x_sw := ax_x.sw;  x_v := ax_x.v_cmd;
ax_y(cw := y_cw, target := y_tgt, pos_fb := y_fb);
y_sw := ax_y.sw;  y_v := ax_y.v_cmd;
ax_z(cw := z_cw, target := z_tgt, pos_fb := z_fb);
z_sw := ax_z.sw;  z_v := ax_z.v_cmd;

(* ---- 应用状态汇总 ---- *)
all_oe := pwr_x.Status AND pwr_y.Status AND pwr_z.Status;
move_done := go_x.Done AND go_y.Done AND go_z.Done;
any_moving := (x_v <> 0) OR (y_v <> 0) OR (z_v <> 0);
fault_any := (x_sw AND 16#0008) <> 0 OR (y_sw AND 16#0008) <> 0 OR (z_sw AND 16#0008) <> 0;
